using ClaimPilot.Models;
using QuestPDF.Fluent;
using QuestPDF.Helpers;

namespace ClaimPilot.Services;

/// <summary>
/// QuestPDF document generation for letters, the lawsuit worksheet, and the
/// evidence packet. All documents carry the general-information footer.
/// </summary>
public static class PdfService
{
    private const string FooterText =
        "Generated by ClaimPilot — general legal information, not legal advice. Verify everything with your court's rules or an attorney.";

    /// <summary>Generates a clean, professional letter PDF from plain text.</summary>
    public static void GenerateLetterPdf(string filePath, string title, string body)
    {
        Document.Create(container =>
        {
            container.Page(page =>
            {
                page.Size(PageSizes.Letter);
                page.Margin(60);
                page.DefaultTextStyle(style => style.FontSize(11));
                page.Header()
                    .PaddingBottom(12)
                    .Text(title)
                    .FontSize(16)
                    .SemiBold();
                page.Content()
                    .Text(body)
                    .LineHeight(1.35f);
                page.Footer()
                    .AlignCenter()
                    .PaddingTop(12)
                    .Text(FooterText)
                    .FontSize(8)
                    .Italic();
            });
        }).GeneratePdf(filePath);
    }

    /// <summary>Generates the small-claims worksheet PDF: parties, amount, facts, checklist.</summary>
    public static void GenerateWorksheetPdf(string filePath, WorksheetExport export)
    {
        Document.Create(container =>
        {
            container.Page(page =>
            {
                page.Size(PageSizes.Letter);
                page.Margin(50);
                page.DefaultTextStyle(style => style.FontSize(11));
                page.Header()
                    .PaddingBottom(10)
                    .Text("Lawsuit Worksheet")
                    .FontSize(18)
                    .SemiBold();

                page.Content().Column(column =>
                {
                    column.Spacing(10);

                    column.Item().Text("Parties").FontSize(13).SemiBold();
                    column.Item().Text($"Plaintiff: {export.PlaintiffName}\n{export.PlaintiffAddress}");
                    column.Item().Text($"Defendant: {export.DefendantName}\n{export.DefendantAddress}");
                    column.Item().Text($"Amount sought: {export.AmountSought}").SemiBold();

                    column.Item().PaddingTop(6).Text("Facts timeline").FontSize(13).SemiBold();
                    if (export.Facts.Count == 0)
                    {
                        column.Item().Text("No facts entered yet.").Italic();
                    }
                    else
                    {
                        column.Item().Table(table =>
                        {
                            table.ColumnsDefinition(def =>
                            {
                                def.RelativeColumn(2);
                                def.RelativeColumn(5);
                            });
                            table.Header(header =>
                            {
                                header.Cell().Text("Date").SemiBold();
                                header.Cell().Text("What happened").SemiBold();
                            });
                            foreach (var fact in export.Facts)
                            {
                                table.Cell().PaddingVertical(3).Text(fact.Date);
                                table.Cell().PaddingVertical(3).Text(fact.Description);
                            }
                        });
                    }

                    column.Item().PaddingTop(6).Text("Petition checklist — what a petition generally includes").FontSize(13).SemiBold();
                    foreach (var item in export.ChecklistTexts)
                    {
                        column.Item().Text("☐  " + item);
                    }

                    column.Item().PaddingTop(6).Text(export.FilingFeeNote).Italic();
                });

                page.Footer()
                    .AlignCenter()
                    .PaddingTop(12)
                    .Text(FooterText)
                    .FontSize(8)
                    .Italic();
            });
        }).GeneratePdf(filePath);
    }

    /// <summary>
    /// Generates a single organized packet: cover page, date-sorted timeline,
    /// and the evidence list noting each attached file's on-device path.
    /// </summary>
    public static void GenerateEvidencePacketPdf(
        string filePath,
        string incidentSummary,
        IReadOnlyList<TimelineEvent> events,
        IReadOnlyList<EvidenceItem> items)
    {
        Document.Create(container =>
        {
            // Cover page.
            container.Page(page =>
            {
                page.Size(PageSizes.Letter);
                page.Margin(60);
                page.DefaultTextStyle(style => style.FontSize(11));
                page.Header()
                    .PaddingBottom(10)
                    .Text("Evidence Packet")
                    .FontSize(20)
                    .SemiBold();
                page.Content().Column(column =>
                {
                    column.Spacing(10);
                    column.Item().Text($"Prepared: {DateTime.Today:MMMM d, yyyy}").Italic();
                    column.Item().Text("Incident summary").FontSize(13).SemiBold();
                    column.Item().Text(string.IsNullOrWhiteSpace(incidentSummary) ? "No summary recorded." : incidentSummary);
                    column.Item().Text("Contents").FontSize(13).SemiBold();
                    column.Item().Text($"Timeline events: {events.Count}\nEvidence items: {items.Count}\n\nAttached files are stored on this PC. File paths are listed next to each evidence item in the evidence section.");
                });
                page.Footer().AlignCenter().PaddingTop(12).Text(FooterText).FontSize(8).Italic();
            });

            // Timeline page(s), sorted by date.
            container.Page(page =>
            {
                page.Size(PageSizes.Letter);
                page.Margin(50);
                page.DefaultTextStyle(style => style.FontSize(11));
                page.Header()
                    .PaddingBottom(10)
                    .Text("Timeline (sorted by date)")
                    .FontSize(16)
                    .SemiBold();
                page.Content().Column(column =>
                {
                    column.Spacing(8);
                    if (events.Count == 0)
                    {
                        column.Item().Text("No timeline events recorded.").Italic();
                    }
                    foreach (var e in events.OrderBy(x => x.EventDate))
                    {
                        column.Item().Column(inner =>
                        {
                            inner.Item().Text($"{e.EventDateDisplay} — {e.Title}").SemiBold();
                            if (!string.IsNullOrWhiteSpace(e.Category))
                            {
                                inner.Item().Text($"Category: {e.Category}").FontSize(9).Italic();
                            }
                            if (!string.IsNullOrWhiteSpace(e.Details))
                            {
                                inner.Item().Text(e.Details);
                            }
                        });
                    }
                });
                page.Footer().AlignCenter().PaddingTop(12).Text(FooterText).FontSize(8).Italic();
            });

            // Evidence list page(s).
            container.Page(page =>
            {
                page.Size(PageSizes.Letter);
                page.Margin(50);
                page.DefaultTextStyle(style => style.FontSize(11));
                page.Header()
                    .PaddingBottom(10)
                    .Text("Evidence list")
                    .FontSize(16)
                    .SemiBold();
                page.Content().Column(column =>
                {
                    column.Spacing(8);
                    if (items.Count == 0)
                    {
                        column.Item().Text("No evidence items recorded.").Italic();
                    }
                    var number = 1;
                    foreach (var item in items)
                    {
                        var index = number++;
                        column.Item().Column(inner =>
                        {
                            inner.Item().Text($"Exhibit {index}: {item.Title}").SemiBold();
                            inner.Item().Text($"Date: {item.ItemDateDisplay}   Category: {item.Category}").FontSize(9).Italic();
                            if (!string.IsNullOrWhiteSpace(item.Description))
                            {
                                inner.Item().Text(item.Description);
                            }
                            inner.Item().Text($"Attached file (on this PC): {item.FilePath}").FontSize(9);
                        });
                    }
                });
                page.Footer().AlignCenter().PaddingTop(12).Text(FooterText).FontSize(8).Italic();
            });
        }).GeneratePdf(filePath);
    }
}
